import fs from "node:fs";
import path from "node:path";

export function resolveSafeExtractPath(destRoot: string, entryName: string): string {
  if (!entryName || entryName.includes("\0")) {
    throw new Error("Invalid archive entry name");
  }
  const root = path.resolve(destRoot);
  const normalizedEntry = entryName.replace(/^[/\\]+/, "");
  const candidate = path.resolve(root, normalizedEntry);
  const rel = path.relative(root, candidate);

  if (!rel || rel.startsWith("..") || path.isAbsolute(rel)) {
    throw new Error(`Archive entry escapes destination root: ${entryName}`);
  }

  let cur = root;
  for (const part of rel.split(path.sep)) {
    cur = path.join(cur, part);
    if (fs.existsSync(cur) && fs.lstatSync(cur).isSymbolicLink()) {
      throw new Error(`Refusing extraction through symlink component: ${cur}`);
    }
  }
  return candidate;
}
