    sum_value = metric_hourly_rollups.sum_value + EXCLUDED.sum_value,
    updated_at = now()
`

func UpsertHourlyRollups(ctx context.Context, db *sql.DB, rows []MetricRollup) error {
	if len(rows) == 0 {
		return nil
	}
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	stmt, err := tx.PrepareContext(ctx, upsertRollupSQL)
	if err != nil {
		return err
	}
	defer stmt.Close()

	for _, r := range rows {
