fn decode_lower_hex_into(src: &[u8], dst: &mut [u8]) -> Result<(), &'static str> {
    if src.len() != dst.len() * 2 {
        return Err("hex slice length mismatch");
    }
    for (i, chunk) in src.chunks_exact(2).enumerate() {
        let hi = decode_lower_hex_nibble(chunk[0])?;
        let lo = decode_lower_hex_nibble(chunk[1])?;
        dst[i] = (hi << 4) | lo;
    }
    Ok(())
