export function buildSafeOtlpConfig(
  rawEndpoint: string,
  rawHeaders: string,
): { endpoint: string; headers: Record<string, string> } {
  const parsedUrl = new URL(rawEndpoint);
  if (parsedUrl.protocol !== "https:" && parsedUrl.protocol !== "http:") {
    throw new Error(`Unsupported OTLP protocol: ${parsedUrl.protocol}`);
  }

  const headers: Record<string, string> = {};
  for (const pair of rawHeaders.split(",")) {
    const trimmed = pair.trim();
    if (!trimmed) continue;
    const eqIdx = trimmed.indexOf("=");
    if (eqIdx <= 0) {
      throw new Error("Malformed OTEL_EXPORTER_OTLP_HEADERS entry");
    }
    const key = trimmed.slice(0, eqIdx).trim();
    const val = decodeURIComponent(trimmed.slice(eqIdx + 1).trim());
    if (!HEADER_NAME_RE.test(key) || /[\r\n\0]/.test(val)) {
      throw new Error(`Unsafe header key or value for ${key}`);
    }
    headers[key] = val;
  }

  const hasHeaders = Object.keys(headers).length > 0;
  if (parsedUrl.protocol === "http:" && hasHeaders && !LOOPBACK_HOSTS.has(parsedUrl.hostname)) {
    throw new Error("Refusing to transmit OTLP headers over non-loopback cleartext HTTP");
  }

  return { endpoint: parsedUrl.toString(), headers };
