        return Err("unsafe PostgreSQL base_table identifier");
    }
    if !(2020..=2100).contains(&year) || !(1..=12).contains(&month) {
        return Err("year or month out of supported range");
    }
    let (next_year, next_month) = if month == 12 {
        (year + 1, 1)
    } else {
        (year, month + 1)
    };
    let part_name = format!("{base_table}_y{year:04}m{month:02}");
    let start_ts = format!("{year:04}-{month:02}-01 00:00:00+00");
    let end_ts = format!("{next_year:04}-{next_month:02}-01 00:00:00+00");
    Ok(format!(
        "CREATE TABLE IF NOT EXISTS {part_name} PARTITION OF {base_table} \
         FOR VALUES FROM ('{start_ts}') TO ('{end_ts}');"
    ))
}
