fn decode_hex_32(hex_str: &str) -> Result<[u8; 32], String> {
    let raw = hex_str.trim().as_bytes();
    if raw.len() != 64 {
        return Err("expected 64-char sha256 hex digest".to_string());
    }
    let mut out = [0u8; 32];
    for (i, pair) in raw.chunks_exact(2).enumerate() {
        let s = std::str::from_utf8(pair).map_err(|_| "invalid utf-8 in hex".to_string())?;
        out[i] = u8::from_str_radix(s, 16).map_err(|_| "invalid hex character".to_string())?;
    }
    Ok(out)
}

pub fn verify_artifact_sha256(
    path: &Path,
    expected_hex: &str,
    max_bytes: u64,
) -> Result<(), String> {
    let expected = decode_hex_32(expected_hex)?;
    let meta = fs::symlink_metadata(path).map_err(|e| format!("stat failed: {e}"))?;
    if !meta.file_type().is_file() {
        return Err("artifact path must be a regular file, not symlink or directory".to_string());
    }
    if meta.len() > max_bytes {
        return Err(format!("artifact size {} exceeds max_bytes {}", meta.len(), max_bytes));
    }

