    let mut limited = file.take(max_bytes.saturating_add(1));
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 8192];
    let mut total: u64 = 0;

    loop {
        let n = limited.read(&mut buf).map_err(|e| format!("read failed: {e}"))?;
        if n == 0 {
