        }
        total += n as u64;
        if total > max_bytes {
            return Err("artifact grew past max_bytes during read".to_string());
        }
        hasher.update(&buf[..n]);
    }

    let actual = hasher.finalize();
    let mut diff = 0u8;
    for (a, b) in actual.iter().zip(expected.iter()) {
        diff |= a ^ b;
    }
    if diff != 0 {
        return Err("artifact sha256 digest mismatch".to_string());
    }
    Ok(())
