    1,
    `gw:sw:${key}`,
    String(Math.trunc(windowMs)),
    String(Math.trunc(maxRequests)),
    reqId,
  )) as [number, number, number];

  return {
    allowed: raw[0] === 1,
    remaining: raw[1],
    retryAfterMs: raw[2],
