func RunGracefulServer(
	parent context.Context,
	srv *http.Server,
	tp *sdktrace.TracerProvider,
	drainTimeout time.Duration,
) error {
	if drainTimeout <= 0 {
		drainTimeout = 10 * time.Second
	}
	sigCtx, stopSignals := signal.NotifyContext(parent, os.Interrupt, syscall.SIGTERM)
	defer stopSignals()

	errCh := make(chan error, 1)
	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
			return
		}
		errCh <- nil
	}()

	var serveErr error
	select {
	case serveErr = <-errCh:
		if serveErr != nil {
			return serveErr
		}
	case <-sigCtx.Done():
		httpCtx, cancelHTTP := context.WithTimeout(context.Background(), drainTimeout)
		serveErr = srv.Shutdown(httpCtx)
		cancelHTTP()
		<-errCh
	}

	if tp != nil {
		otelCtx, cancelOTel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancelOTel()
		if flushErr := tp.Shutdown(otelCtx); flushErr != nil {
			return errors.Join(serveErr, flushErr)
		}
	}
	return serveErr
}
